def recall(query: str, limit: int = 8):
    q = {x for x in str(query).lower().split() if x}
    ranked = []
    for row in LEARNED_EXPERIENCE['facts']:
        text = row['text']
        score = sum(1 for x in q if x in text.lower())
        if score:
            ranked.append((score, row))
    ranked.sort(key=lambda x: (-x[0], x[1]['source_id'], x[1]['text']))
    return [row for _, row in ranked[:max(1, min(int(limit), 32))]]

def component():
    return {'schema': 'yado.learned_recall_capability.v1', 'experience_digest': LEARNED_EXPERIENCE['experience_digest'], 'fact_count': len(LEARNED_EXPERIENCE['facts']), 'external_code_executed': False, 'canonical_active': False}
